<template><div class="page-screen"><header class="page-head"><div><h1 class="page-title">协作空间</h1><p class="page-subtitle">集中维护团队资料，让每一份文件都有清晰的归属。</p></div><button class="btn primary" @click="run(()=>ops.createSpace(router))"><Icon name="plus"/>创建空间</button></header><div class="table-page-body"><div class="toolbar"><h2 class="toolbar-heading">全部空间 <span class="count">{{filtered.length}}</span></h2><div class="toolbar-right"><input class="input directory-search" type="search" v-model="keyword" placeholder="搜索空间"/><select class="input" v-model="sortMode" @change="saveSort"><option value="TIME">创建时间</option><option value="NAME">名称自然排序</option></select></div></div><div class="table-shell"><div class="table-scroll"><div v-if="error" class="empty"><p>{{error}}</p><button class="btn" @click="load">重试</button></div><div v-else-if="busy" class="empty">正在加载…</div><div v-else class="spaces-content"><section class="space-grid"><article v-for="s in paged" :key="s.id" class="space-card"><button class="space-open" :disabled="s.status!=='ACTIVE'" @click="router.push('/workspaces/'+s.id)"><div class="space-cover"><Icon name="people"/><span class="space-cover-label">{{s.status==='ACTIVE'?'协作空间':'已归档'}}</span></div><div class="space-body"><h2 class="space-title">{{s.name}}</h2><p class="space-desc">{{roleName(s.myRole)}} · {{s.creatorName}}创建<span v-if="ui.usage?.workspaces?.[s.id]"> · {{formatSize(ui.usage.workspaces[s.id].activeBytes)}}</span></p><div class="space-foot"><span class="avatar">{{(s.creatorName||'空').slice(0,1)}}</span><span>{{s.memberCount}} 位成员 · {{ui.usage?.workspaces?.[s.id]?.fileCount||0}} 个文件</span><Icon name="arrow" class="small"/></div></div></button><div class="space-tools"><button class="text-button" :disabled="s.status!=='ACTIVE'" @click="run(()=>ops.members(s))">成员</button><button class="icon-button" :aria-label="s.name+'的操作'" @click="spaceMenu($event,s)"><Icon name="more"/></button></div></article></section><div v-if="!filtered.length" class="empty"><div class="empty-symbol"><Icon name="people"/></div><h3>没有匹配的空间</h3><p>可以创建协作空间，或联系空间管理员添加成员。</p></div><div class="info-strip"><Icon name="building"/><span>空间成员按角色访问文件；归档空间会保留文件并停止访问。</span></div></div></div><Pager :total="filtered.length" :page="page" :size="size" @page="goPage" @size="changeSize"/></div></div></div></template>
<script setup>
import {formatFileSize as formatSize} from '../../utils/formatters';
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import * as api from '../api';import * as ops from '../operations';import {ui,run,dialog} from '../state';import Icon from '../components/Icon.vue';import Pager from '../components/Pager.vue';
const route=useRoute(),router=useRouter(),spaces=ref([]),keyword=ref(route.query.keyword||''),sortMode=ref('TIME'),busy=ref(false),error=ref('');let seq=0;
const page=computed(()=>Number(route.query.page)||1),size=computed(()=>Number(route.query.size)||ui.prefs.pageSize);
const collator=new Intl.Collator('zh-CN',{numeric:true,sensitivity:'base'});
const filtered=computed(()=>spaces.value.filter(s=>s.name.toLowerCase().includes(keyword.value.toLowerCase())).sort((a,b)=>(sortMode.value==='NAME'?collator.compare(a.name,b.name):String(b.createdAt).localeCompare(String(a.createdAt)))||String(a.id).localeCompare(String(b.id))));
const paged=computed(()=>filtered.value.slice((page.value-1)*size.value,page.value*size.value));
const roleName=r=>({OWNER:'所有者',ADMIN:'管理员',MEMBER:'成员',VIEWER:'只读'})[r]||r;
function goPage(p){router.replace({query:{...route.query,page:p,keyword:keyword.value||undefined}});}function changeSize(n){router.replace({query:{...route.query,page:1,size:n}});}
async function load(){const n=++seq;busy.value=true;error.value='';try{const [list,p]=await Promise.all([api.getWorkspaces(),api.getWorkspaceSortPreference()]);if(n===seq){spaces.value=list;sortMode.value=p.sortMode||'TIME';}}catch(e){if(n===seq)error.value=e.message;}finally{if(n===seq)busy.value=false;}}
async function saveSort(){await run(()=>api.updateWorkspaceSortPreference(sortMode.value));goPage(1);}
function spaceMenu(e,s){ops.menu(e,[{label:'空间动态',icon:'info',disabled:s.status!=='ACTIVE',run:async()=>{const records=await api.get('/api/workspaces/'+s.id+'/activities');void dialog({title:'空间动态 · '+s.name,records:records.map(r=>({id:r.id,name:r.name,description:r.action+' · '+r.createdAt}))});}},{label:'重命名',icon:'edit',disabled:!['OWNER','ADMIN'].includes(s.myRole)||s.status!=='ACTIVE',run:()=>ops.renameSpace(s)},{label:'归档空间',icon:'trash',disabled:s.myRole!=='OWNER'||s.status!=='ACTIVE',run:()=>ops.archiveSpace(s,router)}]);}
watch(keyword,()=>goPage(1));watch(()=>ui.revision,load);onMounted(load);onUnmounted(()=>seq++);
</script>
